  "dl.f.finale.title": "Sesongavslutning",
  "dl.f.finale.text": "Mester, toppscorere, målgivende og beste karakterer – pluss tabell gjennom alle tider på tvers av sesonger.",
  "dl.f.crest.title": "Din egen logo",
  "dl.f.crest.text": "Velg form og farger. Klubben bærer fargene dine hele veien.",
  "dl.f.fair.title": "Rettferdig for alle",
  "dl.f.fair.text": "Ingen kjemi, moral eller penger. Bare valgene dine og taktikken din avgjør.",
  "dl.shotsTitle": "Se det i aksjon",
  "dl.shotsSub": "Fra lobby til mester – alt i nettleseren.",
  "dl.shot.lobby": "Lobbyen",
  "dl.shot.lobby.text": "Opprett klubben din, inviter venner og chat mens dere venter.",
  "dl.shot.live": "Live-draften",
  "dl.shot.live.text": "Klokka, puljen, banen din og draft-tavlen.",
  "dl.shot.summary": "Avslutningen",
  "dl.shot.summary.text": "Sluttabellen og sesongens beste – og så videre til neste draft.",
  "dl.finalTitle": "Hvem har best øye for en spiller?",
  "dl.finalText": "Opprett en liga, send lenken til vennene dine og finn ut av det i kveld.",
  "land.promoPill": "Ny spilltype",
  "land.promoTitle": "Draftliga: draft drømmelaget ditt med vennene",
  "land.promoText": "Bygg en fiktiv klubb av de 500 beste spillerne – live, med 60 sekunder per valg og voice-chat. Spill deretter en hel sesong mot hverandre på én kveld.",
  "land.promoCta": "Les om draftligaen",
  "dr.grade.A+.1": "Dette er ikke en draft, det er et ran. Alle andre kan like gjerne spille om andreplassen.",
  "dr.grade.A+.2": "Eksperten har ikke flere superlativer. Et lag bygget av en som har sett FOR mye fotball.",
  "dr.grade.A+.3": "Favorittene. Hvis de ikke vinner, er det managerens skyld – ikke draftens.",
  "dr.grade.A.1": "Sterk draft med svært få svake punkter. Resten av ligaen bør være nervøse.",
  "dr.grade.A.2": "Klassisk, solid og farlig. En av de få som faktisk hadde en plan.",
  "dr.grade.A.3": "Toppklasse hele veien ned. Bare benken skiller dem fra et A+.",
  "dr.grade.B+.1": "Bra jobba. Et par valg eksperten rynker på nesen av, men helheten holder.",
  "dr.grade.B+.2": "Over middels og med potensial for overraskelser. Undervurder dem på eget ansvar.",
  "dr.grade.B+.3": "Stjernene er der – nå må bare taktikken henge med.",
  "dr.grade.B.1": "Verken hot eller not. Et lag man glemmer til de stjeler poeng fra en.",
  "dr.grade.B.2": "Midt i flokken. Sesongen avgjøres av taktikken, ikke av draften.",
  "dr.grade.B.3": "Solid håndverk uten store armbevegelser.",
  "dr.grade.C.1": "Eksperten klødde seg i nakken flere ganger underveis. Det er hull.",
  "dr.grade.C.2": "Noen gode navn, men også valg som fikk chatten til å gå amok.",
  "dr.grade.C.3": "Det kan gå – hvis alt går opp i en høyere enhet. Det gjør det sjelden.",
  "dr.grade.D.1": "Var dette en draft eller et lykkehjul? Eksperten er bekymret.",
  "dr.grade.D.2": "Tidlige valg som burde vært tatt mye senere. Eller slett ikke.",
  "dr.grade.D.3": "Underdog-laget. Til gjengjeld kan man bare overraske positivt.",
  "dr.grade.F.1": "Eksperten har lukket øynene og trukket ut støpselet. Lykke til.",
  "dr.grade.F.2": "Var assistenten på ferie? Dette krever et mirakel.",
  "dr.grade.F.3": "Historisk dårlig. Men det står ingenting i reglene om at man ikke kan vinne likevel.",
  "dr.gradesTitle": "Eksperten vurderer draften",
