  "trophy.board.league": "Styret hyller {manager}: {club} er mestere!",
  "trophy.board.league.body": "Lederen: \"Dette er en historisk dag for {club}. {manager} har gitt oss det vi har drømt om – et mesterskap. Styret står 100 % bak deg, og vi gleder oss allerede til neste sesong.\"",
  "trophy.board.leagueAgain": "Styret: {manager} gjør det igjen – mesterskap nr. {n}!",
  "trophy.board.leagueAgain.body": "Lederen: \"Å vinne én gang er stort. Å gjøre det igjen og igjen er en æra. Takk, {manager} – du har gjort {club} til et dynasti.\"",
  "trophy.board.cup": "Styret gratulerer med {comp}!",
  "trophy.board.cup.body": "Lederen: \"Et trofé i skapet – det er akkurat slike kvelder vi gjør dette for. Gratulerer så mye til {manager} og hele troppen.\"",
  "trophy.board.cupAgain": "Styret: {comp} igjen – tittel nr. {n} under {manager}!",
  "trophy.board.cupAgain.body": "Lederen: \"Det begynner å bli en vane, og det er en god vane. Gratulerer, {manager}.\"",
  "trophy.board.europe": "Europeisk triumf! Styret er i ekstase over {comp}",
  "trophy.board.europe.body": "Lederen: \"{club} har vunnet {comp}. Det er den største kvelden i klubbens nyere historie. {manager}, navnet ditt står nå i klubbens historiebøker for alltid.\"",
  "trophy.board.europeAgain": "Styret: {comp} igjen – {manager} er en legende!",
  "trophy.board.europeAgain.body": "Lederen: \"Tittel nr. {n} i {comp}. Det finnes ingen ord. Takk.\"",
  "trophy.fans.league": "Byen går av hengslene – tusenvis av fans feirer mesterskapet",
  "trophy.fans.league.body": "Gatene er fulle av {club}-drakter, flagg og fyrverkeri. I fanforumet heter det bare én ting: \"{manager}, {manager}, {manager}!\"",
  "trophy.fans.cup": "Fansen feirer {comp}-seieren hele natten",
  "trophy.fans.cup.body": "Tribunen sang lenge etter sluttsignalet, og bussen med trofeet ble møtt av jublende fans utenfor stadion.",
  "trophy.fans.europe": "Hele landet feirer {club}s europeiske triumf",
  "trophy.fans.europe.body": "Titusenvis av fans tok imot laget på flyplassen. \"Dette glemmer vi aldri\", lyder det overalt.",
  "trophy.captain.league": "{player}: \"Dette er for deg og fansen, sjef\"",
  "trophy.captain.league.body": "Kapteinen: \"Du fikk oss til å tro på det fra første dag. Hver eneste en i garderoben ville løpt gjennom en vegg for deg. Takk, sjef.\"",
  "trophy.captain.cup": "{player}: \"Du ga oss troen i finalen\"",
  "trophy.captain.cup.body": "Kapteinen: \"Peptalken før kampen satt perfekt. Vi ville vinne denne for deg.\"",
  "trophy.captain.europe": "{player}: \"Den største kvelden i livet mitt – takk, sjef\"",
  "trophy.captain.europe.body": "Kapteinen: \"Som gutt drømte jeg om å løfte dette trofeet. Du gjorde det mulig.\"",
  "trophy.press.league": "Avisen: {manager} – arkitekten bak {club}s mesterskap",
  "trophy.press.league.body": "Ekspertene er enige: taktikken, overgangene og evnen til å få det beste ut av troppen gjorde forskjellen. {manager} nevnes allerede som årets manager.",
  "trophy.press.cup": "Avisen: {manager} leverer trofé til {club}",
  "trophy.press.cup.body": "Cupen er lunefull, men {club} hadde svar på alt. En velfortjent tittel til {manager}.",
  "trophy.press.europe": "Europa hyller {manager}",
  "trophy.press.europe.body": "Medier i hele Europa skriver om {club}s triumf i {comp}. {manager}s navn er plutselig på alles lepper – også hos de største klubbene.",
  "fan.ev.trophy": "Trofé!",
  "reject.reason.future": "\"Du er fremtiden – vi bygger laget rundt deg de kommende årene\"",
  "reject.r.future.2": "{player}: Wow, takk sjef. Det betyr alt for meg. Jeg blir her og viser at du har rett.",
  "reject.r.future.1": "{player}: Det er fint å høre. Men da vil jeg også få sjansen på banen.",
  "reject.r.future.0": "{player}: Fremtiden? Det tror jeg ikke helt på – jeg ser hvem som spiller.",
  "reject.r.future.1Calm": "{player}: Takk, sjef. Jeg hadde uansett ikke dårlig tid med å komme til {club}.",
  "reject.r.future.0Calm": "{player}: Okei… Jeg var ikke så interessert i {club} heller.",
  "talk.future": "Du er fremtiden",
  "talk.futureHint": "Si til et talent at han er klubbens fremtid – virker best på unge med stort potensial",
  "talk.r.futureBelieves": "{player} lyser opp: \"Takk, sjef – jeg skal jobbe hardere enn noensinne for å vise at du har rett.\"",
