  "land.looks.modern.text": "Lyst eller mørkt tema i klubbens farger, sidemeny, store tall og grafer. Bygget for både mobil, nettbrett og datamaskin.",
  "land.looks.classic.text": "Tittellinje i klubbens farger, faner, grønne rullegardinmenyer og spillerne i to kolonner – som du husker det. Med skiftende bakgrunnsbilder og pikselutseende.",
  "land.looks.play.modern": "Spill moderne",
