  "land.s.career.kicker": "Karriere",
  "land.s.career.title": "Skriv din egen historie",
  "land.s.career.text": "Opprykk og nedrykk, cupfinaler, Europa og galakvelder. Bli sparket, søk nye jobber og bli en legende.",
  "land.s.career.b1": "Ekte ligasystemer med sluttspill og splits",
