  "land.s.career.b3": "Ungdomstalenter og spillere som legger opp",
  "land.rankKicker": "Konkurranse",
  "land.rankTitle": "Er du landets beste manager?",
  "land.rankText": "Manager Score belønner oppgaven, ikke bare budsjettet: plassering mot forventning, ligaens styrke, titler, Europa, økonomi og unge spillere. Bare første forsøk på hver sesong teller.",
  "land.rankCta": "Start karrieren din",
  "land.rankBoard": "Rangeringslisten – karriere totalt",
  "land.rankEmpty": "Rangeringslisten er ny. Spill din første sesong og ta førsteplassen.",
  "land.stepsTitle": "Fra avspark til mesterskap på tre klikk",
  "land.step1.title": "Velg klubben din",
  "land.step1.text": "Ta over en storklubb – eller ta utfordringen med en liten klubb i 1. divisjon.",
  "land.step2.title": "Bygg laget ditt",
  "land.step2.text": "Speid, forhandle, tren og finn taktikken som får mest ut av troppen.",
  "land.step3.title": "Klatre på rangeringslisten",
  "land.step3.text": "Hver sesong gir poeng. Del plasseringen din og utfordre vennene.",
  "land.faqTitle": "Ofte stilte spørsmål",
  "land.q1": "Koster det noe?",
  "land.a1": "Nei. Spillet er gratis, og det er ingen reklame eller kjøp i spillet.",
  "land.q2": "Må jeg installere noe?",
  "land.a2": "Nei, det kjører direkte i nettleseren. Du kan installere det som app på mobil og datamaskin, og det fungerer også offline.",
  "land.q3": "Hvor lagres spillet mitt?",
  "land.a3": "Lokalt på enheten din – automatisk, så du kan lukke fanen og fortsette senere. Du kan også eksportere og importere lagrede spill.",
  "land.q4": "Er spillerne ekte?",
  "land.a4": "Ja, over 40 000 ekte spillere i to databaser: fellesskapets October 2026-oppdatering til CM 01/02 (22 700 spillere i sesongen 2026/27) og den originale CM 01/02-databasen fra 2001/02 (35 000 spillere). Egenskapene kommer fra CM-databasene.",
  "land.q5": "Kan jeg spille med vennene mine?",
  "land.a5": "Ja. Opprett et onlinespill, del koden og styr hver deres klubb i samme verden.",
  "land.q6": "Er det det originale Championship Manager?",
  "land.a6": "Nei. Det er et uavhengig fanprosjekt, bygget fra bunnen av og inspirert av de klassiske managerspillene – med masse nye ideer.",
  "land.finalTitle": "Klubben din venter.",
  "land.finalText": "Sesongen starter når du trykker på knappen.",
  "land.footerData": "Spillerdata: transfermarkt-datasets (CC0)",
  "land.disclaimer": "Uoffisielt fanprosjekt. Ikke tilknyttet, godkjent av eller forbundet med Sports Interactive, Square Enix/Eidos eller varemerket Championship Manager. Klubb- og spillernavn tilhører sine respektive eiere.",
